// Template VehicleLane
clock tick;                    // local clock of the lane
int[0, LANE_W-1] pos = 0;

const Direction direction = (lane_y % 2 == 0) ? RIGHT : LEFT;

void move_lane(PosY lane) {
    pos = (LANE_W + pos + direction) % LANE_W;
}

int[0,1] get_cell(LaneX x, PosY lane) {
    return lane_structure[(LANE_W + x pos) % LANE_W];
}

